def transform(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]
    dq=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True; dq.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True; dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and g[ni][nj]==bg and not seen[ni][nj]:
                seen[ni][nj]=True; dq.append((ni,nj))
    return [[4 if g[i][j]==bg and not seen[i][j] else g[i][j] for j in range(w)] for i in range(h)]

